import csv, collections
with open('inputs/ROSMAP_meta_ad.csv', newline='') as f:
    rows=list(csv.DictReader(f))
by=collections.defaultdict(list)
for row in rows: by[row['projid']].append(row)
for sid, group in by.items():
    if len(group)>1:
        print('\\n'+sid, 'n='+str(len(group)))
        cols=list(group[0].keys())
        for i,row in enumerate(group,1):
            print(i, {k: row[k] for k in cols})
PY"

